        );
        let input_row = div().flex().flex_row().items_end().gap_2();
        let previewing = self.preview.is_some();
        let editing = self.editing.is_some();
        let send_tooltip = if queues {
            format!("Queue until the harness is free ({SEND_SHORTCUT})")
        } else {
