        (0x4877a6, 0x335a82)
    } else {
        (0x3674ba, 0x245a96)
    };
    let dim = hex_alpha(0x000000, (p.dim * 255.).round() as u8);

    let mut colors = Map::new();
    let mut set = |key: &str, value: String| {
        colors.insert(key.to_string(), Value::String(value));
    };
    set("background", hex(p.base));
